/*
 * response.c - Response builder + static file serving.
 *
 * For HTTP/1.x we assemble responses as a linked list of "slices":
 *   - header buffer (generated by finalize_headers)
 *   - optional file slice (passed via sendfile for zero-copy in I/O)
 *   - optional gzipped body buffer
 *
 * For HTTP/2 this builder is not used; the H2 layer builds DATA frames
 * directly but reuses all the metadata helpers (content_type, etag, etc).
 */
#include "response.h"
#include <dirent.h>
#include <fcntl.h>
#include <sys/sendfile.h>
#include "cache.h"
#include "metrics.h"
#include "proxy.h"

static slice_t *slice_new(arena_t *a, slice_kind_t k)
{
    slice_t *s = arena_alloc(a, sizeof *s);
    if (!s) return NULL;
    memset(s, 0, sizeof *s);
    s->kind = k;
    return s;
}

void response_init(http_response_t *r, arena_t *a, bool head_only, bool keepalive)
{
    memset(r, 0, sizeof *r);
    r->arena = a;
    r->head_only = head_only;
    r->keepalive = keepalive;
    r->status = HTTP_200;
}

void response_set_status(http_response_t *r, http_status_t s) { r->status = s; }
void response_set_content_type(http_response_t *r, const char *ct)
{
    snprintf(r->content_type, sizeof r->content_type, "%s", ct ? ct : "");
}
void response_set_etag(http_response_t *r, const char *etag)
{
    snprintf(r->etag, sizeof r->etag, "%s", etag ? etag : "");
}

int response_add_buf(http_response_t *r, const void *buf, size_t len)
{
    slice_t *s = slice_new(r->arena, SLICE_BUF);
    if (!s) return -1;
    s->base = buf; s->len = len;
    if (!r->head) r->head = s; else r->tail->next = s;
    r->tail = s;
    /* Only accumulate into total_len for body slices (headers are prepended
     * later by response_finalize_headers and counted via write_total). We
     * detect the body phase by r->has_body being already set, except for
     * error pages that pre-set total_len before adding body. */
    if (r->has_body) r->total_len += len;
    return 0;
}

int response_add_file(http_response_t *r, int fd, off_t off, size_t len)
{
    slice_t *s = slice_new(r->arena, SLICE_FILE);
    if (!s) return -1;
    s->fd = fd; s->file_off = off; s->len = len;
    if (!r->head) r->head = s; else r->tail->next = s;
    r->tail = s;
    r->has_body = true;
    /* total_len is expected to already be set by caller (response_serve_file
     * sets it before calling us); do not add again */
    return 0;
}

int response_add_cstr(http_response_t *r, const char *str)
{ return response_add_buf(r, str, strlen(str)); }

int response_finalize_headers(http_response_t *r, bool tls)
{
    size_t cap = SALUKID_SMALLBUF_SZ;
    char *h = arena_alloc(r->arena, cap);
    if (!h) return -1;
    char *p = h;
    size_t rem = cap;
    int n = snprintf(p, rem,
        "HTTP/1.1 %d %s\r\n"
        "Server: %s\r\n"
        "Date: ", r->status, http_status_text(r->status), SALUKID_SERVER_NAME);
    p += n; rem -= (size_t)n;

    time_t now = time(NULL);
    struct tm gmt;
    gmtime_r(&now, &gmt);
    size_t dl = strftime(p, rem, "%a, %d %b %Y %H:%M:%S GMT", &gmt);
    p += dl; rem -= dl;

    n = snprintf(p, rem, "\r\nContent-Type: %s\r\n",
                 r->content_type[0] ? r->content_type : "application/octet-stream");
    p += n; rem -= (size_t)n;

    if (r->has_body || r->status == HTTP_206 || r->status == HTTP_304 ||
        (r->status >= 400 && r->status < 600) || r->head_only) {
        /* For HEAD, report the actual body length (correct CL), we just
         * don't transmit the bytes. For everything else, report total_len. */
        n = snprintf(p, rem, "Content-Length: %zu\r\n", r->total_len);
        p += n; rem -= (size_t)n;
    }
    if (r->etag[0]) {
        n = snprintf(p, rem, "ETag: %s\r\n", r->etag);
        p += n; rem -= (size_t)n;
    }
    if (r->status == HTTP_206 && r->content_range[0]) {
        n = snprintf(p, rem, "Content-Range: %s\r\n", r->content_range);
        p += n; rem -= (size_t)n;
        n = snprintf(p, rem, "Accept-Ranges: bytes\r\n");
        p += n; rem -= (size_t)n;
    }
    if (r->gzipped) {
        n = snprintf(p, rem, "Content-Encoding: gzip\r\nVary: Accept-Encoding\r\n");
        p += n; rem -= (size_t)n;
    }
    if (!r->keepalive) {
        n = snprintf(p, rem, "Connection: close\r\n");
        p += n; rem -= (size_t)n;
    } else {
        n = snprintf(p, rem, "Connection: keep-alive\r\nKeep-Alive: timeout=%d\r\n",
                     SALUKID_KEEPALIVE_SEC);
        p += n; rem -= (size_t)n;
    }
    size_t hl = append_security_headers(p, rem, tls);
    p += hl; rem -= hl;

    n = snprintf(p, rem, "\r\n");
    p += n;

    size_t hlen = (size_t)(p - h);
    slice_t *s = slice_new(r->arena, SLICE_BUF);
    if (!s) return -1;
    s->base = h; s->len = hlen;
    s->next = r->head;
    r->head = s;
    r->header_len = hlen;
    /* write_total is headers + body for the flush loop */
    r->write_total = hlen + r->total_len;
    return 0;
}

int response_error(http_response_t *r, http_status_t s, const char *msg)
{
    char body[768];
    int n = snprintf(body, sizeof body,
        "<!DOCTYPE html><html><head><title>%d %s</title></head>"
        "<body><h1>%d %s</h1><p>%s</p><hr><address>%s</address></body></html>",
        s, http_status_text(s), s, http_status_text(s),
        msg ? msg : "", SALUKID_SERVER_NAME);
    if (n < 0) n = 0;
    if ((size_t)n >= sizeof body) n = (int)sizeof body - 1;
    response_set_status(r, s);
    response_set_content_type(r, "text/html; charset=utf-8");
    /* overwrite any queued body */
    r->head = r->tail = NULL; r->total_len = 0; r->has_body = false;
    if (!r->head_only) {
        /* Copy body into the arena so it outlives this frame. Do NOT pass
         * the stack pointer directly to response_add_buf -- slices are
         * pointer-sized and non-owning. */
        char *bdup = arena_strndup(r->arena, body, (size_t)n);
        if (!bdup) return -1;
        slice_t *bs = slice_new(r->arena, SLICE_BUF);
        if (!bs) return -1;
        bs->base = bdup;
        bs->len = (size_t)n;
        r->head = r->tail = bs;
        r->has_body = true;
    }
    r->total_len = (size_t)n;
    return 0;
}

/* ---------- File serving ---------- */

static int dir_listing(http_response_t *r, const char *fs_path)
{
    char out[4096];
    int n = snprintf(out, sizeof out,
        "<!DOCTYPE html><html><head><title>Index of directory</title></head>"
        "<body><h1>Index</h1><pre>");
    DIR *d = opendir(fs_path);
    if (!d) return -1;
    struct dirent *de;
    while ((de = readdir(d)) && n < (int)sizeof(out) - 256) {
        if (de->d_name[0] == '.') continue;
        n += snprintf(out + n, sizeof out - (size_t)n,
                      "<a href=\"%s\">%s</a>\n", de->d_name, de->d_name);
    }
    closedir(d);
    n += snprintf(out + n, sizeof out - (size_t)n, "</pre></body></html>");
    if (n < 0) return -1;
    if ((size_t)n >= sizeof out) n = (int)sizeof out - 1;
    response_set_content_type(r, "text/html; charset=utf-8");
    r->has_body = true;
    r->total_len = (size_t)n;
    /* Dup into arena -- slices don't own memory */
    char *bdup = arena_strndup(r->arena, out, (size_t)n);
    if (!bdup) return -1;
    return response_add_buf(r, bdup, (size_t)n);
}

int response_serve_file(http_response_t *r, const char *fs_path,
                        const struct stat *st, bool is_dir,
                        const http_request_t *req)
{
    if (is_dir) {
        /* Directory without index: forbid */
        return response_error(r, HTTP_403, "directory listing restricted");
    }

    /* Range? */
    off_t fsize = st->st_size;
    off_t start = 0, end = fsize - 1;
    bool do_range = false;
    if (req->has_range && req->method == HTTP_M_GET) {
        if (req->range_suffix) {
            off_t suffix = req->range_end; /* suffix length stored in range_end */
            if (suffix >= fsize) { start = 0; }
            else { start = fsize - suffix; }
            end = fsize - 1;
        } else {
            start = req->range_start;
            end = req->range_end > 0 ? req->range_end : fsize - 1;
        }
        if (start >= fsize || end < start)
            return response_error(r, HTTP_416, "range not satisfiable");
        do_range = true;
    }

    /* ETag / 304 */
    char etag[32];
    etag_for(st, etag, sizeof etag);
    response_set_etag(r, etag);
    if (req->has_if_none_match && etag_match(req->if_none_match, etag)) {
        r->status = HTTP_304;
        r->has_body = false;
        r->total_len = 0;
        return 0;
    }

    int fd = open(fs_path, O_RDONLY | O_NONBLOCK | O_CLOEXEC);
    if (fd < 0) return response_error(r, HTTP_404, "not found");

    const char *ct = content_type_for(fs_path, strlen(fs_path));
    response_set_content_type(r, ct);

    size_t len = (size_t)(end - start + 1);
    if (do_range) {
        r->status = HTTP_206;
        /* Content-Range header is prepended to the response header buffer
         * inside an arena-owned slice placed BEFORE the file body. The
         * slice's base points at an arena buffer; finalize_headers()
         * prepends the status + standard headers and our Content-Range
         * slice winds up as a body slice (incorrect). To guarantee
         * ordering, we render Content-Range into a small buffer that
         * finalize_headers will see via the r->extra_headers linked list
         * simulated by a SLICE_BUF placed at the head: instead, emit a
         * synthetic first header-line slice *now* whose text is the
         * "Content-Range: bytes ...\r\n" header. finalize_headers will
         * emit its headers and a final \r\n; we inject the extra header
         * by appending to the header buffer *after* finalize runs.
         * Simpler: write it now into a scratch field... Use a small
         * pre-header trick: set content_range field and emit it in
         * finalize. */
        snprintf(r->content_range, sizeof r->content_range,
                 "bytes %lld-%lld/%lld",
                 (long long)start, (long long)end, (long long)fsize);
    } else {
        r->content_range[0] = '\0';
    }

    r->status = do_range ? HTTP_206 : HTTP_200;
    r->has_body = true;
    r->total_len = len;

    if (!r->head_only) {
        response_add_file(r, fd, start, len);
    }
    return 0;
}
